  const rot=(v,a,b)=>{let [x,y,z]=v;const ca=Math.cos(a),sa=Math.sin(a);[x,y]=[x*ca-y*sa,x*sa+y*ca];const cb=Math.cos(b),sb=Math.sin(b);[y,z]=[y*cb-z*sb,y*sb+z*cb];return [x,z,y]};
