  const S=56;const sym=(p,x,y,lab)=>{const G=el('g',{},g);const fill=aff(p)?'#EF5350':'#0D1B2A';if(p.s==='M')el('rect',{x:x-S/2,y:y-S/2,width:S,height:S,fill,stroke:'#ECEFF1','stroke-width':3},G);else el('circle',{cx:x,cy:y,r:S/2,fill,stroke:'#ECEFF1','stroke-width':3},G);
    if(car(p))el('circle',{cx:x,cy:y,r:8,fill:'#ECEFF1'},G);txt(G,lab,x,y+S/2+24,{size:16,color:'dim',weight:700});const u=el('g',{class:'uni'},G);txt(u,fmt(p),x,y+S/2+46,{size:17,color:'#4FC3F7',weight:800});p.xy=[x,y];return G};
  const ln=(a,b)=>el('path',{d:`M${f2(a[0])},${f2(a[1])} L${f2(b[0])},${f2(b[1])}`,stroke:'#ECEFF1','stroke-width':3,fill:'none'},g);
  const y1=200,y2=420,y3=660,cx=470;[['I',y1],['II',y2],['III',y3]].forEach(([r,y])=>txt(g,r,70,y+8,{size:26,color:'ink',weight:800,anchor:'start'}));
